save(161,dict(paragraphs=['Jnani Debashis Mishra, also published as Jnanee Debasish Mishra, is an Odia poet and literary scholar associated with Ravenshaw University. His poetry collection Daaga received the Sahitya Akademi Yuva Puraskar in 2016. His critical writing includes work on comparative literature, bringing the study of literary relationships alongside his own creative practice.','In “ବାଟଖୋଜା,” the river becomes a teacher of persistence, generosity and the search for a path. Its difficult journey toward the sea contrasts with lives spent choosing comfort. The poem’s later landscape of cement sharpens this contrast into an ecological warning, before returning to the possibility of a living spring within each person.'],sources=[source('Sahitya Akademi — Yuva Puraskar2016 announcement','https://sahitya-akademi.gov.in/pdf/yuvapuraskar-2016.pdf',['Daaga, poetry, Odia, Jnanee Debasish Mishra,2016 award; annexureA page2.']),source('Prachee article deposited in Zenodo — comparative literature','https://zenodo.org/records/12205550',['Author, Ravenshaw affiliation, Odia2024 article Tulanatmaka Sahitya: Bhumi O Akash.'])],identity_match='Name variants, Odia literary practice, specific2016 award and Ravenshaw affiliation match captured biography and poem affiliation.',poems_read=[dict(id=141,title='ବାଟଖୋଜା',basis='Full Odia original read, including trailing affiliation: river/sea, wounds, comfort, cement landscape and inner spring.')],limitations=['Birth year omitted: supplied1985 conflicts with age46 in indexed2023 institutional NIRF record; no reconciliation attempted from inference.','Radio awards and publication counts not independently confirmed; omitted.','No poem content or trailing source affiliation changed.'],next_action='Independent author/editor review; confirm birth details and radio awards before any future use.'))
